'use strict';

var BigInt = require( '@stdlib/bigint/ctor' );
var xorshift128plus = require( './../lib/' );
var i;

// EXAMPLE 1: Create a generator with a seed
console.log( '\n=== Example 1: Basic Generator ===' );

var rng = xorshift128plus({
	'seed': BigInt(12345)
});

console.log( 'Generated 64-bit integers:' );
console.log( '  %s', rng() );
console.log( '  %s', rng() );
console.log( '  %s', rng() );

// EXAMPLE 2: Generate normalized values
console.log( '\n=== Example 2: Normalized Values ===' );

var normalizedRng = xorshift128plus({
	'seed': BigInt(54321)
});

console.log( 'Normalized values in [0, 1):' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %d', normalizedRng.normalized() );
}

// EXAMPLE 3: Reproducibility with same seed
console.log( '\n=== Example 3: Reproducibility ===' );

var rng1 = xorshift128plus({
	'seed': BigInt(99999)
});
var rng2 = xorshift128plus({
	'seed': BigInt(99999)
});

console.log( 'Both generators with same seed (99999n):' );
for ( i = 0; i < 3; i++ ) {
	console.log( '  rng1: %s, rng2: %s', rng1().toString(), rng2().toString() );
}

// EXAMPLE 4: Seeding with different values
console.log( '\n=== Example 4: Different Seeds ===' );

var rngA = xorshift128plus({
	'seed': BigInt(111)
});
var rngB = xorshift128plus({
	'seed': BigInt(222)
});

console.log( 'Different seeds produce different sequences:' );
console.log( '  seed 111n: %s', rngA().toString() );
console.log( '  seed 222n: %s', rngB().toString() );

// EXAMPLE 5: Using without explicit seed (random)
console.log( '\n=== Example 5: Random Seed ===' );

var randomRng = xorshift128plus();

console.log( 'Generator with random seed:' );
for ( i = 0; i < 3; i++ ) {
	console.log( '  %s', randomRng().toString() );
}

// EXAMPLE 6: Accessing generator properties
console.log( '\n=== Example 6: Generator Properties ===' );

var propRng = xorshift128plus({
	'seed': BigInt(777)
});

console.log( 'Generator properties:' );
console.log( '  NAME: %s', propRng.NAME );
console.log( '  seed (BigInt): %s', propRng.seed );
console.log( '  state (array length): %d', propRng.state.length );

// EXAMPLE 7: State management
console.log( '\n=== Example 7: State Management ===' );

var stateRng = xorshift128plus({
	'seed': BigInt(555)
});

console.log( 'Initial values:' );
console.log( '  %s', stateRng() );
console.log( '  %s', stateRng() );

var savedState = stateRng.state;
console.log( 'State saved' );

console.log( 'Continue generating:' );
console.log( '  %s', stateRng() );
console.log( '  %s', stateRng() );

stateRng.state = savedState;
console.log( 'State restored, same values:' );
console.log( '  %s (should be same as value 3)', stateRng() );
console.log( '  %s (should be same as value 4)', stateRng() );

// EXAMPLE 8: Copying a generator
console.log( '\n=== Example 8: Generator Copy ===' );

var original = xorshift128plus({
	'seed': BigInt(333)
});
var duplicate = original.copy();

console.log( 'Original: %s', original() );
console.log( 'Copy:     %s', duplicate() );

console.log( 'Both continue with same sequence (initially):' );
console.log( 'Original: %s', original() );
console.log( 'Copy:     %s', duplicate() );

console.log( 'But now they are independent:' );
console.log( 'Original: %s', original() );
console.log( 'Copy:     %s', duplicate() );
